/usr/bin/bash -lc "source /public/home/shiys/miniconda3/etc/profile.d/conda.sh && conda activate easynco && CUDA_VISIBLE_DEVICES='' PYTHONDONTWRITEBYTECODE=1 python -B - <<'PY'
import csv,json
from pathlib import Path
m=json.loads(Path('code/V4/solver_source_manifest.json').read_text())
for item in m['solvers']:
 print('SOLVER',item['solver_id'],item['solver_name'])
 for d in item['deployments']:
  if 'train' not in d.get('splits',[]): continue
  record={'implementation':d['implementation'],'problems':d['problems'],'binding':d['binding_status'],'checkpoint':d.get('checkpoint'),'checkpoint_candidates':[{k:v for k,v in c.items() if k not in ('sha256',)} for c in d.get('checkpoint_candidates',[])],'checkpoints':d.get('checkpoints'),'resolved_config':d.get('resolved_config'), 'gaps':d.get('gaps')}
  print(json.dumps(record))
for key in ('mtpomo','mvmoe','moses_cada','moses_rf','routefinder','reld_cvrp','reld_moel','reld_mtl','glop_atsp_init_only'):
 impl=m['implementations'].get(key)
 if impl:print('SOURCE_INTERFACE',key,json.dumps(impl))
rows=list(csv.DictReader(Path('code/V4/runs/R57_task_signal_audit/deployment_audit.csv').open()))
print('DEPLOYMENT_HEADER',list(rows[0]))
for row in rows:
 if row['problem'] in ('TSP','CVRP','ATSP','OVRPTW'):
  print('EXISTING_DEPLOYMENT',json.dumps({k:v for k,v in row.items() if k in ('problem','solver','recipe_status','runtime_status','preflight_status','runtime_log','remaining_gaps','historical_binding','train_origins')}))
PY"

